const results = [];

for (const input of $input.all()) {
  // Read Gemini's extracted response
  const raw = input.json.content?.parts?.[0]?.text;

  if (typeof raw !== 'string') {
    throw new Error('Gemini response text is missing');
  }

  // Remove optional Markdown JSON fences
  const cleaned = raw.trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '');

  const invoice = JSON.parse(cleaned);

  if (!Array.isArray(invoice.items) || !invoice.items.length) {
    throw new Error('Invoice has no extracted items');
  }

  // Create one Google Sheets row per product
  for (const item of invoice.items) {
    results.push({
      json: {
        supplier_name: invoice.supplier_name ?? '',
        invoice_number: invoice.invoice_number ?? '',
        date: invoice.date ?? '',
        gstin: invoice.gstin ?? '',
        payment_mode: invoice.payment_mode ?? '',
        description: item.description ?? '',
        qty: item.qty ?? '',
        rate: item.rate ?? '',
        amount: item.amount ?? '',
        gst_percent: item.gst_percent ?? '',
        subtotal: invoice.subtotal ?? '',
        gst_total: invoice.gst_total ?? '',
        round_off: invoice.round_off ?? '',
        grand_total: invoice.grand_total ?? '',
        review_status: 'Pending Review'
      }
    });
  }
}

return results;

const rows = $input.all();
if (!rows.length) throw new Error('No invoice rows received');

const warnings = [];
const TOLERANCE = 0.02;

// Convert monetary values safely
function money(value, name) {
  if (value === null || value === undefined ||
      String(value).trim() === '') {
    warnings.push(`${name} is missing`);
    return null;
  }

  const n = Number(String(value).replace(/[₹,\s]/g, ''));

  if (!Number.isFinite(n) || n < 0) {
    warnings.push(`${name} is invalid`);
    return null;
  }
  return n;
}

function close(a, b) {
  return Math.abs(a - b) <= TOLERANCE;
}

const first = rows[0].json;
const subtotal = money(first.subtotal, 'Subtotal');
const gst = money(first.gst_total, 'GST total');
const roundOff = Number(first.round_off || 0);
const grandTotal = money(first.grand_total, 'Grand total');

if (!first.supplier_name) warnings.push('Supplier missing');
if (!first.invoice_number) warnings.push('Invoice number missing');
if (!first.date) warnings.push('Invoice date missing');

if (!Number.isFinite(roundOff)) {
  warnings.push('Invalid round-off');
}

let calculatedSubtotal = 0;
let allAmountsValid = true;
let calculatedGST = 0;
let allGSTRatesValid = true;

for (const [index, row] of rows.entries()) {
  const d = row.json;
  const prefix = `Item ${index + 1}`;

  if (!d.description) warnings.push(`${prefix}: name missing`);

  const qty = money(d.qty, `${prefix} quantity`);
  const rate = money(d.rate, `${prefix} rate`);
  const amount = money(d.amount, `${prefix} amount`);

  if (qty !== null && rate !== null && amount !== null) {
    if (!close(qty * rate, amount)) {
      warnings.push(`${prefix}: quantity x rate mismatch`);
    }
  }

  if (amount !== null) {
    calculatedSubtotal += amount;
  } else {
    allAmountsValid = false;
  }

  const gstRate = Number(String(d.gst_percent ?? '')
    .replace('%', '').trim());

  if (String(d.gst_percent ?? '').trim() === '' ||
      !Number.isFinite(gstRate) || gstRate < 0 ||
      gstRate > 100 || amount === null) {
    allGSTRatesValid = false;
  } else {
    calculatedGST += amount * gstRate / 100;
  }

  // Check that invoice header values agree across rows
  for (const field of ['supplier_name', 'invoice_number',
    'date', 'subtotal', 'gst_total', 'grand_total']) {
    if (String(d[field] ?? '') !== String(first[field] ?? '')) {
      warnings.push(`${prefix}: inconsistent ${field}`);
    }
  }
}

if (allAmountsValid && subtotal !== null &&
    !close(calculatedSubtotal, subtotal)) {
  warnings.push('Subtotal does not match item amounts');
}

if (subtotal !== null && gst !== null &&
    grandTotal !== null && Number.isFinite(roundOff) &&
    !close(subtotal + gst + roundOff, grandTotal)) {
  warnings.push('Grand total calculation mismatch');
}

// GST check assumes item amounts exclude GST.
// If tax-inclusive, review GST calculation manually.
if (allGSTRatesValid && gst !== null &&
    !close(calculatedGST, gst)) {
  warnings.push('GST mismatch: verify tax-inclusive/exclusive pricing');
}

const uniqueWarnings = [...new Set(warnings)];
const status = uniqueWarnings.length
  ? 'Needs Review'
  : 'Pending Review';

return rows.map((row, index) => ({
  json: {
    ...row.json,
    review_status: status,
    validation_status: uniqueWarnings.length ? 'Flagged' : 'Passed',
    validation_notes: uniqueWarnings.join('; '),
    calculated_subtotal: calculatedSubtotal.toFixed(2),
    calculated_gst_exclusive: calculatedGST.toFixed(2)
  },
  pairedItem: { item: index }
}));

const lookupResults = $input.all();

// Stop if the lookup found an existing invoice.
// This is an extra safety check.
if (lookupResults.some(item => item.json.row_number != null)) {
  return [];
}

// Retrieve the original validated invoice rows.
const originalRows = $('Invoice Validation').all();

if (!originalRows.length) {
  throw new Error('Original invoice rows not found');
}

// Check the incoming result represents a missing invoice.
if (
  lookupResults.length !== 1 ||
  Object.keys(lookupResults[0].json).length !== 0
) {
  throw new Error('Unexpected duplicate lookup result');
}

// Restore the original rows for Google Sheets.
return originalRows.map(item => ({
  json: { ...item.json }
}));
